def assign_idle_robots(self):
    if getattr(self, 'return_probe_paused', False):
        return
    search = getattr(self, 'target_search_active', False) and self.task_state in ('FOUND', 'RALLY') and (not self.fresh_target())
    if self.task_state not in ('EXPLORE', 'FOUND_UNCONFIRMED') and (not search):
        return
    if search and (self.target_scan_robot is not None or any(self.rally_goal_handles.values()) or any(self.rally_goal_pending.values()) or (self.survey_goal_handle is not None) or self.survey_goal_pending):
