    planning_inputs = input_freshness_at(self.input_freshness_details(), planning_started)
    deadline = min((sample['source_time'] + min(sample['ttl_sec'], getattr(self, 'message_freshness_timeout_sec', 5.0)) for (key, sample) in planning_inputs.items() if key != 'headquarters/target_detection' and sample['source_time'] is not None), default=planning_started)

    def lease_current(stage):
