            return False
        if planning_started <= now <= deadline:
            return True
        details = None
        diagnostics = getattr(self, 'planning_lease_diagnostics', None)
        key = (self.task_state, stage)
        if diagnostics is not None and now - diagnostics.get(key, -float('inf')) >= 30.0:
            diagnostics[key] = now
            details = dict(scope='abandoned frozen callback inputs; read-only diagnostics', planning_map=grid_audit_evidence(self.map_data, self.resolution, self.origin, 'ap_delivered_planning_map', self.map_received_at, None), source_map=grid_audit_evidence(self.source_map_data, self.resolution, self.origin, 'ap_delivered_fused_map', self.map_received_at, None), self_return_cells=self.map_self_return_cells, return_maps={name: grid_audit_evidence(value['data'], value['resolution'], value['origin'], 'ap_delivered_robot_map', self.robot_map_received_at[name], None) for (name, value) in self.robot_maps.items() if value is not None}, robot_positions=self.robot_positions, robot_states=self.robot_states, battery_states=self.battery_states, battery_modes=self.battery_modes, exclusions=exclusions, enable_rally=self.enable_rally, initial_search_next=self.initial_search_next, initial_search_visits=list((getattr(self, 'initial_search_visits', None) or {}).values()), initial_search_views=list((getattr(self, 'initial_search_views', None) or {}).values()), target_search_visits=self.target_search_visits, exploration_resume_intents=self.exploration_resume_intents, successful_exploration_legs=self.successful_exploration_legs, rally_charge_requested=self.rally_charge_requested, goal_targets={name: asdict(goal) if goal is not None else None for (name, goal) in self.goal_targets.items()}, goal_routes=self.goal_routes)
        self.consumed_publisher.publish(String(data=json.dumps(dict(event='coordinator_planning_lease_expired', event_time=now, planning_started_at_sec=planning_started, source_deadline_sec=deadline, stage=stage, inputs_at_start=planning_inputs, diagnostic_inputs=details), sort_keys=True)))
        return False
    exclusions = self.active_exclusions()
    candidates = []
    diagnostics = {'frontier_groups': 0, 'groups_with_viewpoints': 0, 'candidate_assignments': 0}
    frontier_data = self.frontier_cache
    geometry_cache = getattr(self, 'frontier_geometry_cache', None)
    if frontier_data is None and geometry_cache is not None and (geometry_cache[0] is self.map_data) and immutable_grid(self.map_data):
        frontier_data = geometry_cache[1]
    traversable = frontier_data[1] if frontier_data is not None else traversable_grid(self.map_data, self.resolution, PATH_CLEARANCE_M)
    travel_fields = {} if search else {name: exploration_distance_field(self.map_data, traversable, self.resolution, self.origin, position) for (name, position) in self.robot_positions.items() if name in self.participating_robots() and position is not None and (self.battery_modes[name] == 'ACTIVE') and (name not in getattr(self, 'rally_charge_requested', {}))}
    self.exploration_travel_choices = {}
    search_gain_cache = {}
    camera_views = list(getattr(self, 'initial_search_views', {}).values())
    lookahead_candidates = {}
    frontier_gain_cache = {}
    self.frontier_charge_lookahead = (self.map_data, getattr(self, 'map_received_at', None), lookahead_candidates, frontier_gain_cache, search_gain_cache)
    self.opportunity_charge_evidence = {}
    resume_intents = getattr(self, 'exploration_resume_intents', {})
    charge_candidates = {}
    for refine in (False, True, 'known_space') if search else (False, True):
        candidates = []
        raw_candidates = []
        candidate_contexts = {}
        scoring_aborted = False
        resume_candidates = set()
        unfunded_candidates = set()
        travel_preferences = {}
        diagnostics['frontier_groups'] = 0
        diagnostics['groups_with_viewpoints'] = 0
        for (robot_name, position) in idle_positions.items():
            if not lease_current('candidate_generation'):
                return
            initial_search = not search and getattr(self, 'enable_rally', False) and getattr(self, 'initial_search_next', {}).get(robot_name, False)
            robot_exclusions = list(exclusions)
            robot_exclusions.extend((other_position for (other_name, other_position) in self.robot_positions.items() if other_name != robot_name and other_name in self.participating_robots() and (self.robot_states[other_name] == 'active') and (other_position is not None)))
            if initial_search:
                visits = [v['position'] for v in self.initial_search_visits.values()]
                robot_candidates = known_space_search_candidates(self.map_data, self.resolution, self.origin, robot_name, position, [*visits, *[p for p in self.robot_positions.values() if p is not None]], robot_exclusions, [p for (name, p) in self.robot_positions.items() if name != robot_name and p is not None], gain_cache=search_gain_cache, face_interest=True, camera_views=camera_views, defer_gain=True)
                initial_search = bool(robot_candidates)
                robot_diagnostics = dict(frontier_groups=0, groups_with_viewpoints=0)
            if refine == 'known_space':
                robot_candidates = known_space_search_candidates(self.map_data, self.resolution, self.origin, robot_name, position, [*self.target_search_visits, *[p for p in self.robot_positions.values() if p is not None]], robot_exclusions, [p for (name, p) in self.robot_positions.items() if name != robot_name and p is not None], gain_cache=search_gain_cache, defer_gain=True)
                robot_diagnostics = dict(frontier_groups=0, groups_with_viewpoints=0)
            elif not initial_search:
                if frontier_data is None:
                    frontier_data = prepare_frontier_data(self.map_data, self.resolution, defer_gain=True)
                    self.frontier_geometry_cache = (self.map_data, frontier_data)
                (robot_candidates, robot_diagnostics) = robot_candidate_assignments(self.map_data, self.resolution, self.origin, robot_name, position, robot_exclusions, frontier_data, distance_field=travel_fields.get(robot_name), **{'blocked_positions': [other for (name, other) in self.robot_positions.items() if name != robot_name and other is not None]} if refine else {})
            diagnostics['frontier_groups'] += robot_diagnostics['frontier_groups']
            diagnostics['groups_with_viewpoints'] += robot_diagnostics['groups_with_viewpoints']
            lookahead_candidates[robot_name] = [row[3] for row in robot_candidates]
            raw_candidates.extend(robot_candidates)
            candidate_contexts[robot_name] = (robot_exclusions, initial_search)

        def refine_candidate_gain(raw):
            nonlocal scoring_aborted
            (_, robot_name, group_id, assignment) = raw
            if scoring_aborted or robot_name in plans:
                return None
            if not lease_current('candidate_generation'):
                scoring_aborted = True
                return None
            if reservations:
                field = route_caches[robot_name].get('field')
                if field is not None:
                    (_, start, escape, _) = field
                    if start is None or any((routes_conflict((grid_to_world(*escape[0], self.resolution, *self.origin),), reserved) for reserved in reservations)):
                        diagnostics['rejected_routes'] += 1
                        return None
                key = (robot_name, assignment.x, assignment.y)
                if key not in route_proposals:
                    blocked = [p for (peer, p) in self.robot_positions.items() if peer != robot_name and p is not None]
                    route_proposals[key] = plan_rally_leg(RallyPose(assignment.x, assignment.y, 0.0), self.map_data, self.resolution, self.origin, self.robot_positions[robot_name], MAX_NAVIGATION_LEG_M, blocked_positions=blocked, clearance_m=PATH_CLEARANCE_M, visible_only=True, route_cache=route_caches[robot_name])
                if not exploration_prefix_can_move(route_proposals[key], self.robot_positions[robot_name], reservations):
                    diagnostics['rejected_routes'] += 1
                    return None
            assignment = resolve_search_gain(assignment, self.map_data, self.resolution, search_gain_cache) if isinstance(assignment.viewpoint, SearchGainBound) else resolve_frontier_gain(assignment, self.map_data, self.resolution, frontier_gain_cache)
            return None if assignment is None else (assignment.utility, robot_name, group_id, assignment)

        def evaluate_candidate(raw):
            nonlocal scoring_aborted
            (_, robot_name, group_id, assignment) = raw
            if scoring_aborted or robot_name in plans:
                return None
            if not lease_current('candidate_budget'):
                scoring_aborted = True
                return None
            (robot_exclusions, initial_search) = candidate_contexts[robot_name]
            battery_factor = self.exploration_battery_factor(robot_name, assignment.path_distance_m, (assignment.x, assignment.y))
            if battery_factor <= 0:
                return None
            utility = assignment.utility * battery_factor
            preference = None if search else HeadquartersControl.frontier_travel_preference(self, robot_name, assignment, travel_fields)
            if preference is not None:
                utility *= preference['factor']
                utility *= preference.get('mission_spatial_diversity', {}).get('factor', 1.0)
            coordinated = Assignment(assignment.viewpoint, assignment.x, assignment.y, assignment.path_distance_m, utility, assignment.navigation_x, assignment.navigation_y, assignment.navigation_yaw)
            if battery_factor < 1.0:
                unfunded_candidates.add((robot_name, coordinated))
            if preference is not None:
                preference.update(base_utility=assignment.utility, information_gain=assignment.viewpoint.information_gain, frontier_group_id=assignment.viewpoint.group_id, frontier_group_size=assignment.viewpoint.group_size, excluded_targets=robot_exclusions, battery_factor=battery_factor, adjusted_utility=utility, nominal_blocked_positions=[p for (other, p) in self.robot_positions.items() if other != robot_name and p is not None] if refine or initial_search else [])
                if initial_search:
                    preference.update(initial_search_visits=list(self.initial_search_visits.values()), initial_search_views=camera_views, search_view_model=dict(radius_m=INFORMATION_RADIUS_M, fov_rad=INITIAL_SEARCH_VIEW_FOV_RAD, heading_bins=16), search_kind='known_space', view_yaw=assignment.navigation_yaw)
                travel_preferences[robot_name, coordinated] = preference
            if not search and interrupted_frontier_is_useful(coordinated, resume_intents.get(robot_name), battery_factor):
                resume_candidates.add((robot_name, coordinated))
            row = (utility, robot_name, group_id, coordinated)
            candidates.append(row)
            diagnostics['candidate_assignments'] = len(candidates)
            return row
        diagnostics['candidate_assignments'] = 0
        diagnostics['generated_candidate_assignments'] = len(raw_candidates)
        diagnostics['reachable_refinement'] = refine
        diagnostics['rejected_routes'] = 0
        diagnostics['stationary_candidates'] = 0
        plans = {}
        routes = {}
        selected = []
        resuming_names = set()
        route_caches = {name: {} for name in idle_positions}
        route_proposals = {}
        reservations = [remaining_rally_route(route, self.robot_positions[name]) for (name, route) in self.goal_routes.items() if self.robot_states[name] == 'active' and route]
        candidate_order = lazy_priority_candidates(raw_candidates, evaluate_candidate, lambda item: frontier_scheduling_score(item[3].utility, not search and interrupted_frontier_is_useful(item[3], resume_intents.get(item[1]), 1.0)), lambda item: frontier_scheduling_score(item[0], (item[1], item[3]) in resume_candidates), refine_bound=refine_candidate_gain)
        for (_, name, _, assignment) in candidate_order:
            if scoring_aborted or not lease_current('route_admission'):
                return
            if name in plans:
                continue
            unfunded = (name, assignment) in unfunded_candidates
            previous_charge = charge_candidates.get(name)
            if unfunded and previous_charge is not None and (assignment.utility <= previous_charge.utility):
                continue
            if any((math.dist((assignment.x, assignment.y), (other.x, other.y)) < MIN_TARGET_SEPARATION_M for other in plans.values())):
                continue
            blocked = [position for (other_name, position) in self.robot_positions.items() if other_name != name and position is not None]
            key = (name, assignment.x, assignment.y)
            if key not in route_proposals:
                route_proposals[key] = plan_rally_leg(RallyPose(assignment.x, assignment.y, 0.0), self.map_data, self.resolution, self.origin, self.robot_positions[name], MAX_NAVIGATION_LEG_M, blocked_positions=blocked, clearance_m=PATH_CLEARANCE_M, visible_only=True, route_cache=route_caches[name])
            plan = route_proposals[key]
            admitted = reserve_rally_prefix(plan, reservations)
            if admitted is None:
                diagnostics['rejected_routes'] += 1
                continue
            (pose, route) = admitted
            if math.dist(self.robot_positions[name], (pose.x, pose.y)) <= NAVIGATION_POSITION_TOLERANCE_M:
                diagnostics['stationary_candidates'] += 1
                continue
            endpoint = world_to_grid(assignment.x, assignment.y, self.resolution, *self.origin)
            field = route_caches[name].get('field')
            if field is None:
                distances = exploration_distance_field(self.map_data, block_dynamic_positions(traversable, self.resolution, self.origin, blocked), self.resolution, self.origin, self.robot_positions[name])
                planned_distance = float('inf') if distances is None else float(distances[endpoint])
            else:
                (_, _, escape, distance_data) = field
                points = [grid_to_world(*cell, self.resolution, *self.origin) for cell in escape]
                planned_distance = float(distance_data[0][endpoint]) * self.resolution + math.dist(self.robot_positions[name], points[0]) + sum((math.dist(a, b) for (a, b) in zip(points, points[1:])))
            factor = self.exploration_battery_factor(name, planned_distance, (assignment.x, assignment.y))
            if factor <= 0:
                continue
            unfunded = unfunded or factor < 1.0
            original_assignment = assignment
            assignment = Assignment(assignment.viewpoint, assignment.x, assignment.y, planned_distance, assignment.utility, assignment.navigation_x, assignment.navigation_y, assignment.navigation_yaw)
            if unfunded:
                if HeadquartersControl.exploration_charge_budget(self, name, assignment) is not None:
                    charge_candidates[name] = assignment
                continue
            if name in getattr(self, 'rally_charge_requested', {}):
                continue
            plans[name] = Assignment(assignment.viewpoint, assignment.x, assignment.y, assignment.path_distance_m, assignment.utility, pose.x, pose.y, pose.yaw if world_to_grid(pose.x, pose.y, self.resolution, *self.origin) != world_to_grid(assignment.x, assignment.y, self.resolution, *self.origin) else original_assignment.navigation_yaw)
            routes[name] = route
            selected.append(name)
            if (name, original_assignment) in resume_candidates:
                resuming_names.add(name)
            if (name, original_assignment) in travel_preferences:
                witness = travel_preferences[name, original_assignment]
                witness.update(planned_distance_m=planned_distance, blocked_positions=blocked)
                if name in resuming_names:
                    witness['resume_intent'] = resume_intents[name]
                witness['continuation_weight'] = FRONTIER_CONTINUATION_WEIGHT if name in resuming_names else 1.0
