            return
        if selected:
            if search:
                self.target_search_basis = 'current_map_known_free_sweep' if refine == 'known_space' else 'current_map_frontiers'
            break
    charge_candidates = {name: assignment for (name, assignment) in charge_candidates.items() if name not in plans}
    if not search:
        for (name, assignment) in plans.items():
            if getattr(self, 'enable_battery', False) and HeadquartersControl.exploration_charge_budget(self, name, assignment, allow_opportunity=True) is not None:
                charge_candidates[name] = assignment
    if charge_candidates:
        if active_explorers or any((mode == 'CHARGING' for mode in self.battery_modes.values())):
            return
        if HeadquartersControl.request_exploration_charge(self, list(charge_candidates.items())):
            return
    if not selected:
        now = self.now()
        if now - self.last_no_assignment_log >= 10.0:
            self.get_logger().warn(f'No safe cooperative frontier assignment: {diagnostics}; positions={self.robot_positions}; candidates={[(name, round(a.x, 3), round(a.y, 3)) for (_, name, _, a) in candidates[:12]]}')
            self.last_no_assignment_log = now
        return
    if not lease_current('dispatch') or not self.fresh_robot_inputs():
        return
    for robot_name in selected:
        assignment = plans[robot_name]
        if robot_name not in resuming_names:
            resume_intents.pop(robot_name, None)
        else:
            self.get_logger().info(f"Resuming {robot_name}'s interrupted search with a current, funded frontier.")
        self.robot_states[robot_name] = 'active'
        self.goal_targets[robot_name] = assignment
        self.goal_routes[robot_name] = routes[robot_name]
        visual = self.exploration_travel_choices.get(robot_name, {}).get('search_kind') == 'known_space'
        if hasattr(self, 'initial_search_goals'):
            self.initial_search_goals[robot_name] = visual
        self.goal_initial_gain[robot_name] = 0 if visual else self.target_information_gain(assignment.x, assignment.y)
        self.get_logger().info(f'Assigned {robot_name} to group {assignment.viewpoint.group_id} at ({assignment.x:.2f}, {assignment.y:.2f}); navigation=({assignment.navigation_x:.2f}, {assignment.navigation_y:.2f}), path={assignment.path_distance_m:.2f} m, gain={assignment.viewpoint.information_gain}, utility={assignment.utility:.1f}')
        self.send_goal(robot_name, assignment)
